    ('灵敏', '这款传感器非常灵敏，能迅速捕捉细微变化。', 'nhạy, nhạy bén, thính', 'líng mǐn', '这款传感器非常灵敏，能迅速捕捉细微变化。', 'nhạy, nhạy bén, thính', 'líng mǐn', 'Zhè kuǎn chuángǎnqì fēicháng língmǐn, néng xùnsù bǔzhuō xìwēi biànhuà.', 'Cảm biến này rất nhạy, có thể nhanh chóng bắt được những thay đổi nhỏ nhất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7a3804db4a64ea9dba497eac.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d8a63446ac487ff31677258b.mp3'),
    ('灵感', '艺术家的作品往往来自突如其来的灵感。', 'linh cảm', 'líng gǎn', '艺术家的作品往往来自突如其来的灵感。', 'linh cảm', 'líng gǎn', 'Yìshùjiā de zuòpǐn wǎngwǎng láizì tūrú qílái de línggǎn.', 'Tác phẩm của nghệ sĩ thường đến từ linh cảm đột ngột.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-674a5c6c565349dc7a18799f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-8f13ea80dc62413b55e338a5.mp3'),
    ('溜', '孩子们在滑冰场上开心地溜冰。', 'trượt', 'liū', '孩子们在滑冰场上开心地溜冰。', 'trượt', 'liū', 'Háizimen zài huábīng chǎng shàng kāixīn de liūbīng.', 'Bọn trẻ đang vui vẻ trượt băng trên sân băng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-3c419b1de279d964fd18c8c0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b63c3d17b347baee390d0b91.mp3'),
    ('淋', '下雨了，没带伞，被雨水淋得满身湿透。', 'ướt', 'lín', '下雨了，没带伞，被雨水淋得满身湿透。', 'ướt', 'lín', 'Xiàyǔ le, méi dài sǎn, bèi yǔshuǐ lín de mǎn shēn shī tòu.', 'Trời mưa rồi, không mang dù, bị nước mưa ướt đẫm người.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-3f979cc22bed8366bb9b2d80.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d1dd27895244d87b7fef7ea8.mp3'),
    ('流露', '他的眼神中流露出浓浓的思念之情。', 'lộ rõ', 'liú lù', '他的眼神中流露出浓浓的思念之情。', 'lộ rõ', 'liú lù', 'Tā de yǎnshén zhōng liúlù chū nóngnòng de sīniàn zhī qíng.', 'Trong ánh mắt anh ấy lộ rõ nỗi nhớ thương sâu sắc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a64ab5e9c5dcde085f7dd8d2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b4cb5295a2a42b7828795d91.mp3'),
    ('流通', '货币在市场上的流通对经济发展非常重要。', 'lưu thông', 'liú tōng', '货币在市场上的流通对经济发展非常重要。', 'lưu thông', 'liú tōng', 'Huòbì zài shìchǎng shàng de liútōng duì jīngjì fāzhǎn fēicháng zhòngyào.', 'Tiền tệ lưu thông trên thị trường rất quan trọng đối với phát triển kinh tế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-4f50e4a166eb0faf804c2ff9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-aff13469a5cd1140ab83d1ef.mp3'),
    ('流浪', '那只小狗因为没有主人而在街头流浪。', 'lang thang, bụi đời', 'liú làng', '那只小狗因为没有主人而在街头流浪。', 'lang thang, bụi đời', 'liú làng', 'Nà zhī xiǎo gǒu yīnwèi méiyǒu zhǔrén ér zài jiētóu liúlàng.', 'Con chó nhỏ đó vì không có chủ nên lang thang trên phố.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-4ad1e9f74622e77fd361ddad.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-56fedd82e57fc5652f9bea99.mp3'),
    ('流氓', '警方加强了对那些流氓行为的打击力度。', 'lưu manh', 'liú máng', '警方加强了对那些流氓行为的打击力度。', 'lưu manh', 'liú máng', 'Jǐngfāng jiāqiáng le duì nàxiē liúmáng xíngwéi de dǎjī lìdù.', 'Cảnh sát tăng cường đánh mạnh vào những hành vi lưu manh đó.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6b4438e208affd2a05e30e1d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-226eb865ed68c7a188a5c0ba.mp3'),
    ('栏目', '这个电视节目有一个专门的科技栏目。', 'chuyên mục', 'lán mù', '这个电视节目有一个专门的科技栏目。', 'chuyên mục', 'lán mù', 'Zhège diànshì jiémù yǒu yī gè zhuānmén de kējì lánmù.', 'Chương trình truyền hình này có một chuyên mục công nghệ riêng biệt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c8d0cf3f4788bbcded9c545f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-37f3b40a766aac63e335edf7.mp3'),
    ('来源', '我们的信息来源都经过了严格的核实。', 'nguồn gốc', 'lái yuán', '我们的信息来源都经过了严格的核实。', 'nguồn gốc', 'lái yuán', 'Wǒmen de xìnxī láiyuán dōu jīngguò le yángé de héshí.', 'Nguồn thông tin của chúng tôi đều được kiểm chứng nghiêm ngặt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a488e93d69cc12961ea26e97.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-1a1fe65be434dc026de9dd1d.mp3'),
    ('来历', '他所讲的故事来历不明，难以相信。', 'lai lịch', 'lái lì', '他所讲的故事来历不明，难以相信。', 'lai lịch', 'lái lì', 'Tā suǒ jiǎng de gùshì láilì bù míng, nányǐ xiāngxìn.', 'Câu chuyện anh ta kể có lai lịch không rõ ràng, khó tin được.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7e6d2853025cd6d04455ec08.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a3880dbb71d0d2e7be971bcd.mp3'),
    ('晾', '雨停了，妈妈把洗好的衣服拿出去晾晒。', 'hong, phơi', 'liàng', '雨停了，妈妈把洗好的衣服拿出去晾晒。', 'hong, phơi', 'liàng', 'Yǔ tíng le, māmā bǎ xǐ hǎo de yīfu ná chūqù liàng shài.', 'Mưa tạnh rồi, mẹ lấy quần áo đã giặt ra phơi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-b3098c786e20392392688dcb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-28ba1f010777995997452eac.mp3'),
    ('搂', '她紧紧搂住孩子，表达自己深深的爱意。', 'ôm', 'lōu', '她紧紧搂住孩子，表达自己深深的爱意。', 'ôm', 'lōu', 'Tā jǐn jǐn lǒu zhù háizi, biǎodá zìjǐ shēnshēn de àiyì.', 'Cô ấy ôm chặt đứa trẻ, bộc lộ tình yêu sâu sắc của mình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-bd58ab838d97e27f516c015e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b8bf16ba09d339f691d5e946.mp3'),
    ('掠夺', '历史上的掠夺行为给当地人民带来了苦难。', 'cướp đoạt', 'lüè duó', '历史上的掠夺行为给当地人民带来了苦难。', 'cướp đoạt', 'lüè duó', 'Lìshǐ shàng de lüèduó xíngwéi gěi dāngdì rénmín dàilái le kǔnàn.', 'Hành vi cướp đoạt trong lịch sử đã mang lại đau khổ cho người dân địa phương.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7225b1462dba621ea2dd6c78.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-15c961114e1e1a16ba4d5594.mp3'),
    ('捞', '渔民每天早上去河里捞鱼，赚取生活费。', 'vớt, mò', 'lāo', '渔民每天早上去河里捞鱼，赚取生活费。', 'vớt, mò', 'lāo', 'Yúmín měitiān zǎoshang qù hé lǐ lāo yú, zhuànqǔ shēnghuófèi.', 'Ngư dân mỗi sáng đều ra sông vớt cá để kiếm tiền sinh sống.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-40049037748fc92353f790ef.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d7a51cc80e2bded75c526f7e.mp3'),
    ('懒惰', '他因为懒惰而没有完成老师布置的作业。', 'lười biếng', 'lǎn duò', '他因为懒惰而没有完成老师布置的作业。', 'lười biếng', 'lǎn duò', 'Tā yīnwèi lǎnduò ér méiyǒu wánchéng lǎoshī bùzhì de zuòyè.', 'Anh ấy vì lười biếng nên không hoàn thành bài tập mà thầy cô giao.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-bb870b55653b48a7e96e6fa1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-609dcf1b9dc5b7f44564a139.mp3'),
    ('愣', '听到这个消息后，她愣在原地，不知所措。', 'ngây ra, sững sờ', 'lèng', '听到这个消息后，她愣在原地，不知所措。', 'ngây ra, sững sờ', 'lèng', 'Tīng dào zhège xiāoxi hòu, tā lèng zài yuándì, bù zhī suǒ cuò.', 'Nghe được tin này, cô ấy đứng sững tại chỗ, không biết phải làm sao.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-45801f23eaf389a76709296a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-6dd5763d7b252f43f7ba1040.mp3'),
    ('廉洁', '作为公务员，他一直坚持廉洁自律，赢得尊重。', 'liêm khiết', 'lián jié', '作为公务员，他一直坚持廉洁自律，赢得尊重。', 'liêm khiết', 'lián jié', 'Zuòwéi gōngwùyuán, tā yīzhí jiānchí liánjié zìlǜ, yíngdé zūnzhòng.', 'Là công chức, anh ta luôn giữ gìn liêm khiết tự kỷ luật, được mọi người tôn trọng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-15edf8e976d70dfb892a7e25.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-c4f20614c7f9473d5fe48971.mp3'),
    ('履行', '公司承诺的合同义务必须在规定时间内履行。', 'thực thi (chức trách), thực hiện (lời hứa)', 'lǚ xíng', '公司承诺的合同义务必须在规定时间内履行。', 'thực thi (chức trách), thực hiện (lời hứa)', 'lǚ xíng', 'Gōngsī chéngnuò de hétonɡ yìwù bìxū zài ɡuīdìnɡ shíjiān nèi lǚxínɡ.', 'Nghĩa vụ hợp đồng mà công ty cam kết phải thực thi trong thời gian quy định.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-4fe1ede684a68578ac317414.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-01bb71c001c99760d24302be.mp3'),
    ('屡次', '他屡次迟到，已经被经理警告过了。', 'nhiều lần', 'lǚ cì', '他屡次迟到，已经被经理警告过了。', 'nhiều lần', 'lǚ cì', 'Tā lǚcì chídào, yǐjīng bèi jīnglǐ jǐngɡào ɡuò le.', 'Anh ấy nhiều lần đến muộn, đã bị quản lý cảnh cáo rồi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-226a0ebbae731f984ddfcc15.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-ccd6994016a7a2a57daed6ac.mp3'),
    ('垄断', '这家大公司垄断了该地区的大部分市场份额。', 'lũng đoạn', 'lǒng duàn', '这家大公司垄断了该地区的大部分市场份额。', 'lũng đoạn', 'lǒng duàn', 'Zhè jiā dà ɡōnɡsī lǒnɡduàn le ɡāi dìqū de dà bùfèn shìchǎnɡ fèné.', 'Công ty lớn này lũng đoạn phần lớn thị trường khu vực đó.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-74efe605b7c8d40b93677e7a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-74d02b972f0d46913c760a39.mp3'),
    ('喇叭', '小朋友兴奋地吹着红色的喇叭庆祝节日。', 'kèn, còi, loa', 'lǎ bā', '小朋友兴奋地吹着红色的喇叭庆祝节日。', 'kèn, còi, loa', 'lǎ bā', 'Xiǎopénɡyǒu xīnɡfèn de chuī zhe hónɡsè de lǎbā qìnɡzhù jiérì.', 'Đứa trẻ háo hức thổi kèn màu đỏ để chúc mừng ngày lễ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-77a2f6224fc7c2d2f56f9b00.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f854f2370511c209b46484b8.mp3'),
    ('啰唆', '她说话啰唆，让人听了感到很烦躁。', 'rườm rà, lắm lời', 'luō suō', '她说话啰唆，让人听了感到很烦躁。', 'rườm rà, lắm lời', 'luō suō', 'Tā shuōhuà luōsuo, rànɡ rén tīnɡ le ɡǎndào hěn fánzào.', 'Cô ấy nói chuyện rườm rà làm người khác nghe thấy rất khó chịu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-f905f230341bed6f17613291.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a4ea96a7cc29f50fc7b1d81a.mp3'),
    ('啦', '快点准备好啦，我们马上就要出发了。', 'đấy, nhé, à, này', 'lā', '快点准备好啦，我们马上就要出发了。', 'đấy, nhé, à, này', 'lā', 'Kuài diǎn zhǔnbèi hǎo la, wǒmen mǎshàng jiù yào chūfā le.', 'Nhanh chuẩn bị đi nhé, chúng ta sắp khởi hành rồi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0f8dc412bb3bb862a73f8feb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-279b7bfde3a31fb0d9bdb939.mp3'),
    ('唠叨', '妈妈总喜欢唠叨我们要注意身体健康。', 'lảm nhảm, lải nhải', 'láo dao', '妈妈总喜欢唠叨我们要注意身体健康。', 'lảm nhảm, lải nhải', 'láo dao', 'Māmā zǒnɡ xǐhuān láodao wǒmen yào zhùyì shēntǐ jiànkāng.', 'Mẹ luôn lải nhải rằng chúng ta phải chú ý đến sức khỏe.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-33d62befc4d484bfdd641e1b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-42ad19a798bfa7fd736f6081.mp3'),
    ('吝啬', '他太吝啬，甚至不愿意花钱买礼物。', 'keo kiệt', 'lìn sè', '他太吝啬，甚至不愿意花钱买礼物。', 'keo kiệt', 'lìn sè', 'Tā tài lìnsè, shènzhì bù yuànyì huā qián mǎi lǐwù.', 'Anh ấy keo kiệt đến mức thậm chí không muốn tiêu tiền mua quà.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-ee10866ace4f63b0fd8814e4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-6c297a1f84367c3fab65d369.mp3'),
    ('历来', '我国历来重视教育的发展和改革。', 'từ trước đến nay, từ xa xưa trở lại đây', 'lì lái', '我国历来重视教育的发展和改革。', 'từ trước đến nay, từ xa xưa trở lại đây', 'lì lái', 'Wǒɡuó lìlái zhònɡshì jiàoyù de fāzhǎn hé ɡǎɡé.', 'Nước ta từ trước đến nay luôn coi trọng sự phát triển và cải cách giáo dục.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-975a0c81001062c888a8fab2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-3a3c3ef30141c52f9ddf04c2.mp3'),
    ('历代', '历代帝王都在这座宫殿中居住过。', 'đời đời', 'lì dài', '历代帝王都在这座宫殿中居住过。', 'đời đời', 'lì dài', 'Lìdài dìwánɡ dōu zài zhè zuò ɡōnɡdiàn zhōnɡ jūzhù ɡuò.', 'Các đời vua chúa đều đã từng cư trú trong cung điện này.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a03f695bda6ae02a3b752c51.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-4247c96b0b09100b07a99720.mp3'),
    ('力求', '我们力求在下个月完成这个重要项目。', 'cố gắng, phấn đấu', 'lì qiú', '我们力求在下个月完成这个重要项目。', 'cố gắng, phấn đấu', 'lì qiú', 'Wǒmen lìqiú zài xià ɡè yuè wánchéng zhè ɡe zhònɡyào xiànɡmù.', 'Chúng tôi cố gắng hoàn thành dự án quan trọng này vào tháng tới.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-d2920a601eadd9e384680fdc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-ae40e3fef423840f951c0820.mp3'),
    ('力所能及', '遇到需要帮助的人，我们应该尽力所能及地支持。', 'làm hết khả năng', 'lì suǒ néng jí', '遇到需要帮助的人，我们应该尽力所能及地支持。', 'làm hết khả năng', 'lì suǒ néng jí', 'Yù dào xūyào bāngzhù de rén, wǒmen yīnɡɡāi jìn lì suǒ nénɡ jí de zhīchí.', 'Khi gặp người cần giúp đỡ, chúng ta nên làm hết khả năng để hỗ trợ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7b4d887c2e84a892989d12b8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-326b9c8243c1a3e53be668b2.mp3'),
    ('力争', '他力争在今年获得更多的科研成果。', 'cố gắng, phấn đấu', 'lì zhēng', '他力争在今年获得更多的科研成果。', 'cố gắng, phấn đấu', 'lì zhēng', 'Tā lìzhēng zài jīnnián huòdé ɡènɡ duō de kēyán chénɡguǒ.', 'Anh ấy cố gắng phấn đấu đạt được nhiều thành quả nghiên cứu khoa học hơn trong năm nay.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-b3aeeae4b7a799567b9cdd01.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-6dcba3ebe8362e1af7e02aef.mp3'),
    ('利害', '他的棋艺利害，经常在比赛中获胜。', 'lợi hại, giỏi', 'lì hài', '他的棋艺利害，经常在比赛中获胜。', 'lợi hại, giỏi', 'lì hài', 'Tā de qíyì lìhài, jīnɡchánɡ zài bǐsài zhōnɡ huòshènɡ.', 'Kỹ thuật cờ của anh ấy rất lợi hại, thường xuyên thắng trong các cuộc thi đấu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-1c8654d3208799be159c1f52.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-90b1648d5790a0437d31f188.mp3'),
    ('列举', '老师列举了几个成功的案例来说明观点。', 'liệt kê, nêu ra', 'liè jǔ', '老师列举了几个成功的案例来说明观点。', 'liệt kê, nêu ra', 'liè jǔ', 'Lǎoshī lièjǔ le jǐ ɡè chénɡɡōnɡ de ànlì lái shuōmínɡ ɡuāndiǎn.', 'Giáo viên nêu ra một vài ví dụ thành công để minh họa quan điểm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7141aee5145387eca22ee1a1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-1644e2050cc88b7d7755e7bb.mp3'),
    ('凌晨', '他们在凌晨三点才结束了辛苦的工作。', 'sáng sớm', 'líng chén', '他们在凌晨三点才结束了辛苦的工作。', 'sáng sớm', 'líng chén', 'Tāmen zài língchén sān diǎn cái jiéshù le xīnkǔ de ɡōnɡzuò.', 'Họ đến tận sáng sớm ba giờ mới kết thúc công việc vất vả.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a57e324fcc596a4f1498722f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b422d04cfec51d6824002440.mp3')
)
update public.template_cards as card
set
  pinyin = repaired.pinyin,
  meaning_vi = repaired.meaning_vi,
  example_cn = repaired.example_cn,
  example_pinyin = repaired.example_pinyin,
  example_vi = repaired.example_vi,
  word_audio_url = repaired.word_audio_url,
  sentence_audio_url = repaired.sentence_audio_url
from public.template_decks as deck,
  repaired_hsk as repaired
where card.template_deck_id = deck.id
  and deck.slug = 'hsk6-co-ban'
  and card.chinese = repaired.chinese;

with repaired_hsk (
  chinese,
