  sentence_audio_url
) as (
  values
    ('坚韧', '他展现了坚韧的意志，克服了所有困难。', 'vững chắc', 'jiān rèn', '他展现了坚韧的意志，克服了所有困难。', 'vững chắc', 'jiān rèn', 'Tā zhǎnxiàn le jiān rèn de yìzhì, kèfú le suǒyǒu kùnnán.', 'Anh ấy thể hiện ý chí vững chắc, vượt qua mọi khó khăn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-8e44926ca5db650e9392dd85.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a573b6dfad0eaaf45320f790.mp3'),
    ('坚硬', '这块岩石非常坚硬，连锤子都敲不开。', 'cứng', 'jiān yìng', '这块岩石非常坚硬，连锤子都敲不开。', 'cứng', 'jiān yìng', 'Zhè kuài yánshí fēicháng jiān yìng, lián chuízi dōu qiāo bù kāi.', 'Viên đá này rất cứng, ngay cả búa cũng không đập vỡ được.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-68b1dcc033979f4461a0cf80.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a3347369596f6bcc11708820.mp3'),
    ('坚实', '他靠着坚实的基础，实现了自己的梦想。', 'chắc chắn', 'jiān shí', '他靠着坚实的基础，实现了自己的梦想。', 'chắc chắn', 'jiān shí', 'Tā kào zhe jiān shí de jīchǔ, shíxiàn le zìjǐ de mèngxiǎng.', 'Anh ấy dựa vào nền tảng chắc chắn để thực hiện giấc mơ của mình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-e1ef0959663396970eb8fd08.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-da4c1eee29faedb6c71e85b2.mp3'),
    ('坚定', '她对理想的追求始终保持坚定的态度。', 'kiên định', 'jiān dìng', '她对理想的追求始终保持坚定的态度。', 'kiên định', 'jiān dìng', 'Tā duì lǐxiǎng de zhuīqiú shǐzhōng bǎochí jiān dìng de tàidù.', 'Cô ấy luôn giữ thái độ kiên định trong việc theo đuổi lý tưởng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-93f22bd2402fb4f021ef92dc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-07961bac631f6e3b9b2c1315.mp3'),
    ('坚固', '这座桥梁结构坚固，能够承受大风大雨。', 'kiên cố', 'jiān gù', '这座桥梁结构坚固，能够承受大风大雨。', 'kiên cố', 'jiān gù', 'Zhè zuò qiáoliáng jiégòu jiān gù, nénggòu chéngshòu dà fēng dà yǔ.', 'Cây cầu này có kết cấu kiên cố, có thể chịu được gió lớn và mưa to.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-02f0762991948e5998e543be.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-0399483c84c259b453fe66ae.mp3'),
    ('咀嚼', '他细细咀嚼每一口食物，享受美味。', 'nhai, nghiền', 'jǔ jué', '他细细咀嚼每一口食物，享受美味。', 'nhai, nghiền', 'jǔ jué', 'Tā xìxì jǔjué měi yī kǒu shíwù, xiǎngshòu měiwèi.', 'Anh ấy nhai kỹ từng miếng thức ăn, tận hưởng hương vị thơm ngon.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c3d9943497f029baa3577b4c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-4f94af11ceeb089114f08ec3.mp3'),
